void MarqueeUpdate::show()
{
    bool isTracing = Debug::isTracing(HobString("MarqueeMessages"));

    if (isTracing == false)
    {
#if defined(LINUX_FIX)
        Debug::addTraceCategory( std::string("MarqueeMessages") );
#else
        Debug::addTraceCategory("MarqueeMessages");
#endif
    }

    Debug::trace("MarqueeMessages", "MarqueeUpdate: ");

    EvolMessage::show();

    Debug::trace("MarqueeMessages", "display text: ");
    Debug::trace("MarqueeMessages", displayText_);


    if (mqBufferType_ == MqProduct)
    {
        Debug::trace("MarqueeMessages", "update buffer: product");
    }
    else if (mqBufferType_ == MqDaily)
    {
        Debug::trace("MarqueeMessages", "update buffer: daily");
    }
    else if (mqBufferType_ == MqPermanent)
    {
        Debug::trace("MarqueeMessages", "update buffer: permanent");
    }
    else
    {
        Debug::trace("MarqueeMessages", HobString("update buffer: Unknown ") +
                HobString(Integer::toString((UINT16) mqBufferType_)));
    }


    if (isTracing == false)
    {
#if defined(LINUX_FIX)
        Debug::removeTraceCategory( std::string("MarqueeMessages") );
#else
        Debug::removeTraceCategory("MarqueeMessages");
#endif
    }

}

